/* KWin's blur for a window: the regions it names are blurred behind the window's content, through the blur protocol
 * that KDE Plasma's compositor offers on Wayland. The protocol's client code is generated by build.rs. */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <wayland-client.h>

#include "kde-blur-client.h"

struct blur {
    struct wl_surface *surface;
    struct org_kde_kwin_blur *object;
    struct blur *next;
};

static struct wl_compositor *compositor;
static struct org_kde_kwin_blur_manager *manager;
static struct blur *blurs;
static int connected;

static void global_added(void *data, struct wl_registry *registry, uint32_t name, const char *interface,
                         uint32_t version) {
    (void)data;
    if (strcmp(interface, wl_compositor_interface.name) == 0) {
        compositor = wl_registry_bind(registry, name, &wl_compositor_interface, version < 4 ? version : 4);
    } else if (strcmp(interface, org_kde_kwin_blur_manager_interface.name) == 0) {
        manager = wl_registry_bind(registry, name, &org_kde_kwin_blur_manager_interface, 1);
    }
}

static void global_removed(void *data, struct wl_registry *registry, uint32_t name) {
    (void)data;
    (void)registry;
    (void)name;
}

static const struct wl_registry_listener registry_listener = {global_added, global_removed};

/* Asks the display for the compositor's globals. They arrive as GTK dispatches its events, so the blur is not
 * available until then: rsimgv_kde_blur_set returns 0 until it is. */
void rsimgv_kde_blur_connect(struct wl_display *display) {
    struct wl_registry *registry;
    if (connected || display == NULL) {
        return;
    }
    connected = 1;
    registry = wl_display_get_registry(display);
    wl_registry_add_listener(registry, &registry_listener, NULL);
}

static struct blur *find_blur(struct wl_surface *surface) {
    struct blur *blur;
    for (blur = blurs; blur != NULL; blur = blur->next) {
        if (blur->surface == surface) {
            return blur;
        }
    }
    return NULL;
}

/* Blurs the `count` regions of `rects` (x, y, width, height, four ints each) behind `surface`, or stops blurring it
 * when there are none. Returns 0 if the compositor's blur is not available yet. */
int rsimgv_kde_blur_set(struct wl_surface *surface, int count, const int *rects) {
    struct blur *blur;
    struct wl_region *region;
    int i;

    if (manager == NULL || compositor == NULL || surface == NULL) {
        return 0;
    }
    blur = find_blur(surface);
    if (count <= 0) {
        if (blur != NULL) {
            struct blur **link = &blurs;
            while (*link != blur) {
                link = &(*link)->next;
            }
            *link = blur->next;
            org_kde_kwin_blur_manager_unset(manager, surface);
            org_kde_kwin_blur_release(blur->object);
            free(blur);
        }
        return 1;
    }
    if (blur == NULL) {
        blur = calloc(1, sizeof *blur);
        if (blur == NULL) {
            return 0;
        }
        blur->surface = surface;
        blur->object = org_kde_kwin_blur_manager_create(manager, surface);
        blur->next = blurs;
        blurs = blur;
    }
    region = wl_compositor_create_region(compositor);
    for (i = 0; i < count; i++) {
        wl_region_add(region, rects[4 * i], rects[4 * i + 1], rects[4 * i + 2], rects[4 * i + 3]);
    }
    /* The compositor applies these on the surface's next commit, which GTK makes when the window is drawn. */
    org_kde_kwin_blur_set_region(blur->object, region);
    org_kde_kwin_blur_commit(blur->object);
    wl_region_destroy(region);
    return 1;
}
